import {
  ApiError,
  CheckoutPaymentIntent,
  Client,
  Environment,
  OrderApplicationContextShippingPreference,
  OrderApplicationContextUserAction,
  OrdersController,
} from '@paypal/paypal-server-sdk';
import type { ApiResponse, OAuthToken, Order } from '@paypal/paypal-server-sdk';
import type { Config } from './config.js';
import { PayPalApiError } from './errors.js';
import { getToken } from './http.js';

/**
 * The official PayPal Server SDK (generated by APIMatic) handles Orders.
 * Its defaults are unsafe for a CLI (timeout 0 = wait forever, 0 retries), so we set both,
 * and we hand it our own cached token so there is one auth path and one masking path.
 */
export function sdkClient(cfg: Config): Client {
  return new Client({
    environment: cfg.env === 'live' ? Environment.Production : Environment.Sandbox,
    timeout: cfg.timeoutMs,
    httpClientOptions: {
      timeout: cfg.timeoutMs,
      // the SDK only retries GET/PUT by default, which is what we want for money-moving POSTs
      retryConfig: { maxNumberOfRetries: 2, retryOnTimeout: true },
    },
    clientCredentialsAuthCredentials: {
      oAuthClientId: cfg.clientId,
      oAuthClientSecret: cfg.clientSecret,
      oAuthTokenProvider: async (): Promise<OAuthToken> => {
        const t = await getToken(cfg);
        return {
          accessToken: t.accessToken,
          tokenType: 'Bearer',
          expiresIn: BigInt(t.expiresIn),
          expiry: BigInt(Math.floor(t.obtainedAt / 1000) + t.expiresIn),
          scope: t.scopes.join(' '),
        };
      },
    },
  });
}

/** Turns the SDK's ApiError (typed CustomError or bare) into our PayPalApiError. */
export function fromSdkError(err: unknown, method: string, path: string, cfg: Config): unknown {
  if (!(err instanceof ApiError)) {
    // Transport failures come from the SDK's axios adapter, e.g. "timeout of 20000ms exceeded".
    if (err instanceof Error && !(err instanceof PayPalApiError)) {
      const msg = /timeout/i.test(err.message)
        ? `timed out after ${cfg.timeoutMs} ms (slow network? raise PAYPAL_CLI_TIMEOUT_MS)`
        : err.message;
      return new Error(`${method} ${path} failed: ${msg}`);
    }
    return err;
  }
  let payload: unknown = err.result;
  if (payload === undefined && typeof err.body === 'string') {
    try {
      payload = JSON.parse(err.body);
    } catch {
      payload = err.body;
    }
  }
  const debugId = err.headers?.['paypal-debug-id'];
  return PayPalApiError.fromPayload(err.statusCode, payload, { method, path, env: cfg.env }, debugId);
}

/** Prefer the raw wire JSON (snake_case, exactly what PayPal sent) for output. */
function wire(res: ApiResponse<Order>): Record<string, unknown> {
  if (typeof res.body === 'string' && res.body) {
    try {
      return JSON.parse(res.body) as Record<string, unknown>;
    } catch {
      /* fall through */
    }
  }
  return res.result as unknown as Record<string, unknown>;
}

export interface CreateOrderInput {
  amount: string;
  currency: string;
  description?: string;
  requestId?: string;
  returnUrl: string;
  cancelUrl: string;
}

export async function createOrder(cfg: Config, input: CreateOrderInput): Promise<Record<string, unknown>> {
  const orders = new OrdersController(sdkClient(cfg));
  try {
    const res = await orders.createOrder({
      body: {
        intent: CheckoutPaymentIntent.Capture,
        purchaseUnits: [
          {
            amount: { currencyCode: input.currency, value: input.amount },
            description: input.description,
          },
        ],
        applicationContext: {
          brandName: 'paypal-cli test',
          shippingPreference: OrderApplicationContextShippingPreference.NoShipping,
          userAction: OrderApplicationContextUserAction.PayNow,
          returnUrl: input.returnUrl,
          cancelUrl: input.cancelUrl,
        },
      },
      paypalRequestId: input.requestId,
      prefer: 'return=representation',
    });
    return wire(res);
  } catch (err) {
    throw fromSdkError(err, 'POST', '/v2/checkout/orders', cfg);
  }
}

export async function getOrder(cfg: Config, id: string): Promise<Record<string, unknown>> {
  const orders = new OrdersController(sdkClient(cfg));
  try {
    return wire(await orders.getOrder({ id }));
  } catch (err) {
    throw fromSdkError(err, 'GET', `/v2/checkout/orders/${id}`, cfg);
  }
}

export async function captureOrder(cfg: Config, id: string, requestId?: string): Promise<Record<string, unknown>> {
  const orders = new OrdersController(sdkClient(cfg));
  try {
    return wire(
      await orders.captureOrder({ id, paypalRequestId: requestId, prefer: 'return=representation' }),
    );
  } catch (err) {
    throw fromSdkError(err, 'POST', `/v2/checkout/orders/${id}/capture`, cfg);
  }
}
